usdtA = GuildTypeByUsdt[guildType] - GuildTypeByUsdt[userGuildType[user]];
userGuildType[user] = guildType;

USDT.safeTransferFrom(user,receiverAddress,usdtA);

emit AddGuild(user,usdtA,guildType,block.timestamp);
